import { readFileSync } from 'node:fs';
import { RouteGeometry } from '../domain/geo.js';
import type { RouteSignal } from '../domain/types.js';
import type { Db } from '../db.js';

/** Shape of server/data/routes.json (generated by scripts/fetch-routes.mjs). */
export interface RouteSeed {
  id: string;
  city: string;
  name: string;
  hospital: { id: string; name: string; lat: number; lng: number };
  distanceM: number;
  osrmDurationS: number;
  coordinates: [number, number][];
  signals: { code: string; name: string; lat: number; lng: number }[];
}

export interface CatalogRoute {
  id: string;
  city: string;
  name: string;
  hospitalId: string;
  geometry: RouteGeometry;
  coordinates: [number, number][];
  signals: RouteSignal[];
}

export function loadRouteSeeds(path: URL | string): RouteSeed[] {
  return (JSON.parse(readFileSync(path, 'utf8')) as { routes: RouteSeed[] }).routes;
}

/**
 * Pre-saved routes with their signals placed along them. This is the fallback
 * the blueprint asks for: the demo never depends on a live routing API.
 */
export class RouteCatalog {
  private readonly byId = new Map<string, CatalogRoute>();
  private readonly byHospital = new Map<string, CatalogRoute>();

  constructor(seeds: RouteSeed[], db: Db) {
    const sigRows = db.prepare('SELECT id, code, name, lat, lng, route_id FROM signals').all() as unknown as {
      id: number;
      code: string;
      name: string;
      lat: number;
      lng: number;
      route_id: string;
    }[];
    for (const seed of seeds) {
      const geometry = new RouteGeometry(seed.coordinates);
      const signals = sigRows
        .filter((s) => s.route_id === seed.id)
        .map((s) => ({ id: s.id, code: s.code, name: s.name, lat: s.lat, lng: s.lng, alongM: geometry.project(s).alongM }))
        .sort((a, b) => a.alongM - b.alongM)
        .map((s, i) => ({ ...s, order: i + 1 }));
      const route: CatalogRoute = {
        id: seed.id,
        city: seed.city,
        name: seed.name,
        hospitalId: seed.hospital.id,
        geometry,
        coordinates: seed.coordinates,
        signals,
      };
      this.byId.set(route.id, route);
      this.byHospital.set(route.hospitalId, route);
    }
  }

  get(id: string): CatalogRoute | undefined {
    return this.byId.get(id);
  }

  forHospital(hospitalId: string): CatalogRoute | undefined {
    return this.byHospital.get(hospitalId);
  }

  all(): CatalogRoute[] {
    return [...this.byId.values()];
  }
}
